import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

const configuredUrl = import.meta.env.VITE_SUPABASE_URL as string | undefined;
const configuredKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string | undefined;
const isConfigured = Boolean(
  configuredUrl && configuredKey &&
  !configuredUrl.includes('YOUR_PROJECT_ID') &&
  !configuredKey.includes('YOUR_SUPABASE')
);

// Keep the app renderable before credentials are configured. App.tsx shows a
// setup screen in this state, so these fallback values are never used for data.
const SUPABASE_URL = isConfigured ? configuredUrl! : 'http://127.0.0.1:54321';
const SUPABASE_PUBLISHABLE_KEY = isConfigured ? configuredKey! : 'setup-required';

export const supabaseConfigured = isConfigured;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
  }
});
